def transform(grid):
 h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
 # Bounding boxes of substantial color components, restore noise inside their boxes.
 from collections import deque
 seen=set(); boxes=[]
 for r in range(h):
  for c in range(w):
   col=grid[r][c]
   if col in (0,3,4,6) or (r,c) in seen: continue
   q=[(r,c)]; seen.add((r,c)); comp=[]
   while q:
    x,y=q.pop(); comp.append((x,y))
    for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
     if 0<=a<h and 0<=b<w and grid[a][b]==col and (a,b) not in seen: seen.add((a,b)); q.append((a,b))
   if len(comp)>=4: boxes.append((col,min(x for x,y in comp),max(x for x,y in comp),min(y for x,y in comp),max(y for x,y in comp)))
 for r in range(h):
  for c in range(w):
   if grid[r][c] in (0,4,6):
    opts=[(col,r1,r2,c1,c2) for col,r1,r2,c1,c2 in boxes if r1<=r<=r2 and c1<=c<=c2]
    out[r][c]=opts[0][0] if opts else 3
 return out
